problems.solutionCode:
function collectCandidates(modules) {
  const candidates = new Map();
  const collisionSet = new Set();
  for (const mod of modules) {
    for (const entry of mod.exports) {
      if (entry.kind === 'default' && !entry.alias) {
        continue;
      }
      const publicName = entry.alias ?? entry.name;
      if (candidates.has(publicName)) {
        collisionSet.add(publicName);
      } else {
        candidates.set(publicName, {
          sourceModule: mod.moduleName,
          originalName: entry.name,
        });
      }
    }
  }
  return { candidates, collisionSet };
}

function buildBarrelExportMap(modules) {
  if (!Array.isArray(modules)) {
    throw new TypeError('modules must be an array');
  }
  const { candidates, collisionSet } = collectCandidates(modules);
  const exports = {};
  for (const [publicName, target] of candidates.entries()) {
    if (!collisionSet.has(publicName)) {
      exports[publicName] = target;
    }
  }
  return {
    exports,
    collisions: Array.from(collisionSet).sort(),
  };
}

module.exports = { buildBarrelExportMap };

