function resolveModuleImports(moduleTable, importSpecs) {
  const bindings = {};
  for (const spec of importSpecs) {
    const mod = moduleTable[spec.from];
    if (!mod) {
      throw new Error(`Missing module: ${spec.from}`);
    }
    if (spec.kind === 'default') {
      const matched = mod.namedExports.find((name) => name === spec.symbol);
      bindings[spec.localName] = {
        source: spec.from,
        resolvedExport: matched,
      };
    } else {
      const resolved = mod.namedExports.includes(spec.symbol)
        ? spec.symbol
        : mod.defaultExport;
      bindings[spec.localName] = {
        source: spec.from,
        resolvedExport: resolved,
      };
    }
  }
  return bindings;
}

module.exports = { resolveModuleImports };

problems.solutionCode:
function resolveSingleImport(moduleTable, spec) {
  const mod = moduleTable[spec.from];
  if (!mod) {
    throw new Error(`Missing module: ${spec.from}`);
  }
  if (spec.kind === 'default') {
    if (!mod.defaultExport) {
      throw new Error(`Module ${spec.from} has no default export`);
    }
    return { source: spec.from, resolvedExport: mod.defaultExport };
  }
  if (spec.kind === 'named') {
    if (!mod.namedExports.includes(spec.symbol)) {
      throw new Error(`Module ${spec.from} has no named export ${spec.symbol}`);
    }
    return { source: spec.from, resolvedExport: spec.symbol };
  }
  throw new Error(`Unsupported import kind: ${spec.kind}`);
}

function resolveModuleImports(moduleTable, importSpecs) {
  if (!moduleTable || !Array.isArray(importSpecs)) {
    throw new TypeError('Invalid moduleTable or importSpecs');
  }
  const bindings = {};
  for (const spec of importSpecs) {
    bindings[spec.localName] = resolveSingleImport(moduleTable, spec);
  }
  return bindings;
}

module.exports = { resolveModuleImports };

