problems.starterCode:
function evaluateModuleGraph(modules, entryName) {
  const visited = new Set();
  const order = [];

  function visit(name) {
    if (visited.has(name)) {
      return { status: 'tdz-error', module: name, from: name, symbol: 'cycle' };
    }
    visited.add(name);
    const mod = modules[name];
    for (const dep of mod.deps) {
      const res = visit(dep);
      if (res.status !== 'ok') {
        return res;
      }
    }
    order.push(name);
    return { status: 'ok', order };
  }

  return visit(entryName);
}

module.exports = { evaluateModuleGraph };

problems.solutionCode:
function findTdzRead(modName, topLevelReads, state) {
  for (const read of topLevelReads) {
    if (state.get(read.from) === 'visiting') {
      return {
        status: 'tdz-error',
        module: modName,
        from: read.from,
        symbol: read.symbol,
      };
    }
  }
  return null;
}

function evaluateModuleGraph(modules, entryName) {
  if (!modules || !modules[entryName]) {
    throw new Error(`Unknown entry module: ${entryName}`);
  }
  const state = new Map();
  const order = [];

  function visit(name) {
    const currentState = state.get(name);
    if (currentState === 'evaluated' || currentState === 'visiting') {
      return null;
    }
    state.set(name, 'visiting');
    const mod = modules[name];
    if (!mod) {
      throw new Error(`Unknown dependency module: ${name}`);
    }
    for (const dep of mod.deps) {
      const err = visit(dep);
      if (err) {
        return err;
      }
    }
    const tdzErr = findTdzRead(name, mod.topLevelReads, state);
    if (tdzErr) {
      return tdzErr;
    }
    state.set(name, 'evaluated');
    order.push(name);
    return null;
  }

  return visit(entryName) ?? { status: 'ok', order };
}

module.exports = { evaluateModuleGraph };

